CREATE TABLE IF NOT EXISTS continental_regions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, description text, status text NOT NULL DEFAULT 'Planned');
CREATE TABLE IF NOT EXISTS jurisdictions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), region_id uuid REFERENCES continental_regions(id), country_name text NOT NULL UNIQUE, iso_code text, capital text, currency text, legal_family text, constitutional_status text NOT NULL DEFAULT 'Unreviewed', market_status text NOT NULL DEFAULT 'Planned', local_entity_required boolean NOT NULL DEFAULT true, local_partner_required boolean NOT NULL DEFAULT false, foreign_ownership_review_required boolean NOT NULL DEFAULT true, status text NOT NULL DEFAULT 'Planned', evidence_reference text, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE jurisdictions ADD COLUMN IF NOT EXISTS region_id uuid REFERENCES continental_regions(id);
ALTER TABLE jurisdictions ADD COLUMN IF NOT EXISTS capital text;
ALTER TABLE jurisdictions ADD COLUMN IF NOT EXISTS legal_family text;
ALTER TABLE jurisdictions ADD COLUMN IF NOT EXISTS constitutional_status text NOT NULL DEFAULT 'Unreviewed';
ALTER TABLE jurisdictions ADD COLUMN IF NOT EXISTS market_status text NOT NULL DEFAULT 'Planned';
ALTER TABLE jurisdictions ADD COLUMN IF NOT EXISTS local_entity_required boolean NOT NULL DEFAULT true;
ALTER TABLE jurisdictions ADD COLUMN IF NOT EXISTS local_partner_required boolean NOT NULL DEFAULT false;
ALTER TABLE jurisdictions ADD COLUMN IF NOT EXISTS foreign_ownership_review_required boolean NOT NULL DEFAULT true;
ALTER TABLE jurisdictions ADD COLUMN IF NOT EXISTS evidence_reference text;
CREATE TABLE IF NOT EXISTS jurisdiction_regimes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid REFERENCES jurisdictions(id) ON DELETE CASCADE, regime_type text NOT NULL, regime_name text NOT NULL, authority_name text, licence_or_approval text, summary text, mandatory_review boolean NOT NULL DEFAULT true, evidence_reference text, status text NOT NULL DEFAULT 'Unreviewed', UNIQUE(jurisdiction_id,regime_type));
CREATE TABLE IF NOT EXISTS jurisdiction_entity_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid REFERENCES jurisdictions(id) ON DELETE CASCADE, entity_type text NOT NULL, incorporation_route text, ownership_rule text, minimum_capital_reference text, director_or_officer_rule text, filing_requirement text, foreign_investor_rule text, evidence_reference text, status text NOT NULL DEFAULT 'Unreviewed');
CREATE TABLE IF NOT EXISTS jurisdiction_land_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid REFERENCES jurisdictions(id) ON DELETE CASCADE, tenure_type text NOT NULL, holder_type text, acquisition_rule text, lease_rule text, customary_rights_rule text, community_consultation_rule text, foreigner_rule text, evidence_reference text, status text NOT NULL DEFAULT 'Unreviewed');
CREATE TABLE IF NOT EXISTS jurisdiction_asset_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid REFERENCES jurisdictions(id) ON DELETE CASCADE, asset_class text NOT NULL, ownership_rule text, licence_rule text, transfer_rule text, community_rights_gate boolean NOT NULL DEFAULT false, environmental_gate boolean NOT NULL DEFAULT false, evidence_reference text, status text NOT NULL DEFAULT 'Unreviewed');
CREATE TABLE IF NOT EXISTS jurisdiction_authorities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid REFERENCES jurisdictions(id) ON DELETE CASCADE, authority_type text NOT NULL, authority_name text NOT NULL, mandate_summary text, official_reference text, evidence_reference text, status text NOT NULL DEFAULT 'Unverified');
CREATE TABLE IF NOT EXISTS jurisdiction_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid REFERENCES jurisdictions(id) ON DELETE CASCADE, review_type text NOT NULL, reviewer_reference text NOT NULL, reviewed_date date, findings text, risk_rating text, decision text NOT NULL DEFAULT 'Pending', evidence_reference text, status text NOT NULL DEFAULT 'Open');
CREATE TABLE IF NOT EXISTS jurisdiction_accessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid REFERENCES jurisdictions(id), accession_type text NOT NULL, requested_date date, constitutional_review_status text NOT NULL DEFAULT 'Pending', legal_review_status text NOT NULL DEFAULT 'Pending', tax_review_status text NOT NULL DEFAULT 'Pending', regulatory_review_status text NOT NULL DEFAULT 'Pending', rights_review_status text NOT NULL DEFAULT 'Pending', entity_setup_status text NOT NULL DEFAULT 'Pending', board_decision text NOT NULL DEFAULT 'Pending', effective_date date, evidence_reference text, status text NOT NULL DEFAULT 'Proposed');
INSERT INTO continental_regions(code,name,description,status) SELECT 'WA','West Africa','West African jurisdictions supported by the continental framework.','Active' WHERE NOT EXISTS (SELECT 1 FROM continental_regions WHERE code='WA');
INSERT INTO continental_regions(code,name,description,status) SELECT 'EA','East Africa','East African jurisdictions supported by the continental framework.','Planned' WHERE NOT EXISTS (SELECT 1 FROM continental_regions WHERE code='EA');
INSERT INTO continental_regions(code,name,description,status) SELECT 'CA','Central Africa','Central African jurisdictions supported by the continental framework.','Planned' WHERE NOT EXISTS (SELECT 1 FROM continental_regions WHERE code='CA');
INSERT INTO continental_regions(code,name,description,status) SELECT 'NA','North Africa','North African jurisdictions supported by the continental framework.','Planned' WHERE NOT EXISTS (SELECT 1 FROM continental_regions WHERE code='NA');
INSERT INTO continental_regions(code,name,description,status) SELECT 'SA','Southern Africa','Southern African jurisdictions supported by the continental framework.','Planned' WHERE NOT EXISTS (SELECT 1 FROM continental_regions WHERE code='SA');
INSERT INTO jurisdictions(country_name,iso_code,capital,currency,market_status,status) SELECT 'Nigeria','NG','Abuja','NGN','Home Market','Active' WHERE NOT EXISTS (SELECT 1 FROM jurisdictions WHERE country_name='Nigeria');